import { createApi, fetchBaseQuery } from "@reduxjs/toolkit/query/react";

export interface Property {
  id: number;
  propertyTitle: string;
  agencyId: number;
  propertyTypeId: number;
  propertyTypeName: string;
  description: string;
  amenities: string;
  monthlyRent: number;
  location: string;
  unitsAvailable: number;
  applicationDeadline: string;
  status: string;
  createdBy: string;
  createdDate: string;
  isDeleted: boolean;
  deletedDate: string;
  deletedBy: string;
  updatedDate: string;
  updatedBy: string;
}

export interface PropertyResponse {
  data: Property[];
  message: string;

  // Pagination information
  totalCount: number;
  pageNumber: number;
  pageSize: number;
}

export interface GetAllPropertyParams {
  pageSize: number;
  pageNumber: number;
  searchTerm?: string;
  statusFilter?: string;
}

export const propertyApi = createApi({
  reducerPath: "propertyApi",

  baseQuery: fetchBaseQuery({
    baseUrl: "https://localhost:7083/api/",
    prepareHeaders: (headers) =&gt; {
      const token = localStorage.getItem("token");

      if (token) {
        headers.set("Authorization", `Bearer ${token}`);
      }

      headers.set("Content-Type", "application/json");

      return headers;
    },
  }),

  tagTypes: ["Property"],

  endpoints: (builder) =&gt; ({
    getAllProperty: builder.query&lt;
      PropertyResponse,
      GetAllPropertyParams
    &gt;({
      query: ({
        pageSize,
        pageNumber,
        searchTerm = "",
        statusFilter = "",
      }) =&gt; ({
        url: "Property/GetAllProperty",
        method: "GET",
        params: {
          PageSize: pageSize,
          PageNumber: pageNumber,
          SearchTerm: searchTerm,
          statusFilter: statusFilter,
        },
      }),

      providesTags: ["Property"],
    }),
  }),
});

export const {
  useGetAllPropertyQuery,
} = propertyApi; ```



