```import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { FaEdit, FaTrash, FaSearch } from "react-icons/fa";
import { useGetAllPropertyQuery } from "../services/propertyApi";

const PAGE_SIZE = 10;

const PropertyTable = () =&gt; {
  const navigate = useNavigate();

  // -----------------------------
  // State
  // -----------------------------
  const [pageNumber, setPageNumber] = useState(1);

  const [searchInput, setSearchInput] = useState("");

  const [searchTerm, setSearchTerm] = useState("");

  const [statusFilter, setStatusFilter] = useState("");

  // -----------------------------
  // Role
  // -----------------------------
  const role = localStorage.getItem("role");

  const isTenant = role?.toLowerCase() === "tenant";

  // -----------------------------
  // API
  // -----------------------------
  const {
    data,
    isLoading,
    isFetching,
    isError,
  } = useGetAllPropertyQuery({
    pageSize: PAGE_SIZE,
    pageNumber,
    searchTerm,
    statusFilter,
  });

  // -----------------------------
  // Debounce Search
  // -----------------------------
  useEffect(() =&gt; {
    const timer = setTimeout(() =&gt; {
      setPageNumber(1);
      setSearchTerm(searchInput);
    }, 500);

    return () =&gt; clearTimeout(timer);
  }, [searchInput]);

  // -----------------------------
  // Data
  // -----------------------------
  const properties = data?.data ?? [];

  const totalCount = data?.totalCount ?? 0;

  const totalPages = Math.ceil(
    totalCount / PAGE_SIZE
  );

  // -----------------------------
  // Apply
  // -----------------------------
  const handleApply = (propertyId: number) =&gt; {
    navigate(`/application-form/${propertyId}`);
  };

  // -----------------------------
  // Edit
  // -----------------------------
  const handleEdit = (propertyId: number) =&gt; {
    console.log("Edit Property:", propertyId);

    // Future:
    // navigate(`/property/edit/${propertyId}`);
  };

  // -----------------------------
  // Delete
  // -----------------------------
  const handleDelete = (propertyId: number) =&gt; {
    console.log("Delete Property:", propertyId);

    // Future delete mutation
  };

  // -----------------------------
  // Status Color
  // -----------------------------
  const getStatusStyle = (status: string) =&gt; {
    switch (status.toLowerCase()) {
      case "available":
        return "bg-green-100 text-green-700";

      case "rented":
        return "bg-red-100 text-red-700";

      case "onhold":
        return "bg-yellow-100 text-yellow-700";

      default:
        return "bg-gray-200 text-gray-700";
    }
  };

  // -----------------------------
  // Loading
  // -----------------------------
  if (isLoading) {
    return (
      &lt;div className="flex justify-center py-10"&gt;
        &lt;p className="text-gray-700"&gt;
          Loading properties...
        &lt;/p&gt;
      &lt;/div&gt;
    );
  }

  // -----------------------------
  // Error
  // -----------------------------
  if (isError) {
    return (
      &lt;div className="py-10 text-center text-red-600"&gt;
        Failed to load properties.
      &lt;/div&gt;
    );
  }

  return (
    &lt;div className="w-full rounded-xl border border-gray-300 bg-white shadow-sm"&gt;

      {/* =================================
          HEADER
      ================================= */}
      &lt;div className="flex flex-col gap-4 border-b border-gray-300 px-6 py-4 md:flex-row md:items-center md:justify-between"&gt;

        &lt;h2 className="text-xl font-semibold text-gray-900"&gt;
          Properties
        &lt;/h2&gt;

        {/* Search */}
        &lt;div className="relative w-full md:w-80"&gt;
          &lt;FaSearch
            className="absolute left-3 top-1/2
                       -translate-y-1/2 text-gray-500"
            size={14}
          /&gt;

          &lt;input
            type="text"
            value={searchInput}
            onChange={(e) =&gt;
              setSearchInput(e.target.value)
            }
            placeholder="Search properties..."
            className="w-full rounded-lg border border-gray-400
                       bg-white py-2 pl-9 pr-3
                       text-gray-900 outline-none
                       placeholder:text-gray-500
                       focus:border-blue-500
                       focus:ring-2 focus:ring-blue-200"
          /&gt;
        &lt;/div&gt;

        {/* Status Filter */}
        &lt;select
          value={statusFilter}
          onChange={(e) =&gt; {
            setStatusFilter(e.target.value);
            setPageNumber(1);
          }}
          className="rounded-lg border border-gray-400
                     bg-white px-3 py-2
                     text-gray-800 outline-none
                     focus:border-blue-500
                     focus:ring-2 focus:ring-blue-200"
        &gt;
          &lt;option value=""&gt;All Status&lt;/option&gt;
          &lt;option value="Available"&gt;Available&lt;/option&gt;
          &lt;option value="Rented"&gt;Rented&lt;/option&gt;
          &lt;option value="OnHold"&gt;OnHold&lt;/option&gt;
        &lt;/select&gt;
      &lt;/div&gt;

      {/* =================================
          TABLE
      ================================= */}
      &lt;div className="overflow-x-auto"&gt;

        &lt;table className="w-full text-left text-sm"&gt;

          {/* HEADER */}
          &lt;thead className="bg-gray-300 text-gray-900"&gt;
            &lt;tr&gt;

              &lt;th className="whitespace-nowrap px-6 py-4 font-semibold"&gt;
                Property Name
              &lt;/th&gt;

              &lt;th className="whitespace-nowrap px-6 py-4 font-semibold"&gt;
                Monthly Rent
              &lt;/th&gt;

              &lt;th className="whitespace-nowrap px-6 py-4 font-semibold"&gt;
                Location
              &lt;/th&gt;

              &lt;th className="whitespace-nowrap px-6 py-4 font-semibold"&gt;
                Units Available
              &lt;/th&gt;

              &lt;th className="whitespace-nowrap px-6 py-4 font-semibold"&gt;
                Application Deadline
              &lt;/th&gt;

              &lt;th className="whitespace-nowrap px-6 py-4 font-semibold"&gt;
                Status
              &lt;/th&gt;

              {isTenant &amp;&amp; (
                &lt;th className="px-6 py-4 text-center font-semibold"&gt;
                  Apply
                &lt;/th&gt;
              )}

              {!isTenant &amp;&amp; (
                &lt;th className="px-6 py-4 text-center font-semibold"&gt;
                  Action
                &lt;/th&gt;
              )}

            &lt;/tr&gt;
          &lt;/thead&gt;

          {/* BODY */}
          &lt;tbody className="divide-y divide-gray-300"&gt;

            {properties.length === 0 ? (
              &lt;tr&gt;
                &lt;td
                  colSpan={7}
                  className="px-6 py-12 text-center"
                &gt;
                  &lt;p className="text-gray-700"&gt;
                    No properties found.
                  &lt;/p&gt;
                &lt;/td&gt;
              &lt;/tr&gt;
            ) : (
              properties.map((property) =&gt; (
                &lt;tr
                  key={property.id}
                  className="transition hover:bg-gray-100"
                &gt;

                  {/* Property */}
                  &lt;td className="px-6 py-4 font-medium text-gray-900"&gt;
                    {property.propertyTitle}
                  &lt;/td&gt;

                  {/* Rent */}
                  &lt;td className="px-6 py-4 font-medium text-gray-800"&gt;
                    ₹
                    {property.monthlyRent.toLocaleString(
                      "en-IN"
                    )}
                  &lt;/td&gt;

                  {/* Location */}
                  &lt;td className="px-6 py-4 text-gray-700"&gt;
                    {property.location}
                  &lt;/td&gt;

                  {/* Units */}
                  &lt;td className="px-6 py-4 text-gray-700"&gt;
                    {property.unitsAvailable}
                  &lt;/td&gt;

                  {/* Deadline */}
                  &lt;td className="px-6 py-4 text-gray-700"&gt;
                    {new Date(
                      property.applicationDeadline
                    ).toLocaleDateString("en-IN")}
                  &lt;/td&gt;

                  {/* Status */}
                  &lt;td className="px-6 py-4"&gt;

                    &lt;span
                      className={`inline-flex rounded-full
                        px-3 py-1 text-xs font-semibold
                        ${getStatusStyle(
                          property.status
                        )}`}
                    &gt;
                      {property.status}
                    &lt;/span&gt;

                  &lt;/td&gt;

                  {/* ===========================
                      TENANT
                  =========================== */}
                  {isTenant &amp;&amp; (
                    &lt;td className="px-6 py-4 text-center"&gt;

                      &lt;button
                        type="button"
                        onClick={() =&gt;
                          handleApply(property.id)
                        }
                        className="rounded-lg bg-blue-600
                                   px-4 py-2
                                   font-medium text-white
                                   transition
                                   hover:bg-blue-700"
                      &gt;
                        Apply
                      &lt;/button&gt;

                    &lt;/td&gt;
                  )}

                  {/* ===========================
                      ADMIN / MANAGER
                  =========================== */}
                  {!isTenant &amp;&amp; (
                    &lt;td className="px-6 py-4"&gt;

                      &lt;div className="flex items-center justify-center gap-4"&gt;

                        {/* Edit */}
                        &lt;button
                          type="button"
                          title="Edit Property"
                          onClick={() =&gt;
                            handleEdit(property.id)
                          }
                          className="text-blue-600
                                     transition
                                     hover:text-blue-800"
                        &gt;
                          &lt;FaEdit size={18} /&gt;
                        &lt;/button&gt;

                        {/* Delete */}
                        &lt;button
                          type="button"
                          title="Delete Property"
                          onClick={() =&gt;
                            handleDelete(property.id)
                          }
                          className="text-red-600
                                     transition
                                     hover:text-red-800"
                        &gt;
                          &lt;FaTrash size={18} /&gt;
                        &lt;/button&gt;

                      &lt;/div&gt;

                    &lt;/td&gt;
                  )}

                &lt;/tr&gt;
              ))
            )}

          &lt;/tbody&gt;
        &lt;/table&gt;
      &lt;/div&gt;

      {/* =================================
          PAGINATION
      ================================= */}
      &lt;div className="flex flex-col gap-3 border-t border-gray-300
                      px-6 py-4 sm:flex-row
                      sm:items-center sm:justify-between"&gt;

        {/* Information */}
        &lt;p className="text-sm text-gray-600"&gt;
          Showing page{" "}
          &lt;span className="font-semibold text-gray-900"&gt;
            {pageNumber}
          &lt;/span&gt;{" "}
          of{" "}
          &lt;span className="font-semibold text-gray-900"&gt;
            {totalPages || 1}
          &lt;/span&gt;
        &lt;/p&gt;

        {/* Buttons */}
        &lt;div className="flex gap-2"&gt;

          &lt;button
            type="button"
            disabled={pageNumber === 1 || isFetching}
            onClick={() =&gt;
              setPageNumber((prev) =&gt; prev - 1)
            }
            className="rounded-lg border border-gray-400
                       bg-white px-4 py-2
                       text-sm font-medium text-gray-700
                       transition hover:bg-gray-100
                       disabled:cursor-not-allowed
                       disabled:opacity-50"
          &gt;
            Previous
          &lt;/button&gt;

          &lt;button
            type="button"
            disabled={
              pageNumber &gt;= totalPages ||
              isFetching
            }
            onClick={() =&gt;
              setPageNumber((prev) =&gt; prev + 1)
            }
            className="rounded-lg border border-gray-400
                       bg-white px-4 py-2
                       text-sm font-medium text-gray-700
                       transition hover:bg-gray-100
                       disabled:cursor-not-allowed
                       disabled:opacity-50"
          &gt;
            Next
          &lt;/button&gt;

        &lt;/div&gt;
      &lt;/div&gt;

      {/* Fetching indicator */}
      {isFetching &amp;&amp; (
        &lt;div className="border-t border-gray-200 px-6 py-2 text-center"&gt;
          &lt;span className="text-xs text-gray-500"&gt;
            Updating...
          &lt;/span&gt;
        &lt;/div&gt;
      )}

    &lt;/div&gt;
  );
};

export default PropertyTable;```
